export const BODY: string = "\n<p>تصویر کو Base64 کے طور پر ایمبیڈ کرنا مفت فائدہ لگتا ہے۔ ایک کم درخواست، سنبھالنے کے لیے کوئی الگ فائل نہیں، اور تصویر اسی لمحے ظاہر ہوتی ہے جب صفحہ لوڈ ہوتا ہے۔</p>\n<p>فائدہ حقیقی ہے، مگر یہ مفت نہیں۔ ایمبیڈ شدہ تصویر ایک تہائی زیادہ بائٹ لیتی ہے، الگ سے کیش نہیں ہو سکتی، اور آپ کے کوڈ کو پڑھنا اور سنبھالنا مشکل بنا دیتی ہے۔</p>\n<p>اس مضمون میں فیصلے کا ڈھانچہ دیا گیا ہے: سائز کی حدیں، کیشنگ کی ریاضی، اور وہ صورت حال جہاں ایمبیڈ کرنا مدد کرتا ہے اور جہاں نقصان پہنچاتا ہے۔</p>\n<h2 id=\"the-embed-decision\">ایمبیڈ کا فیصلہ ایک پیراگراف میں</h2>\n<p>تصویر کو تب ایمبیڈ کریں جب وہ چھوٹی، ضروری اور مستحکم ہو۔ چھوٹا آئیکن جو ہر صفحے کو چاہیے ہو، جو شاذ و نادر بدلے، اور جسے الگ لانے میں پوری درخواست لگے۔</p>\n<p>تصویر کو تب لنک کریں جب وہ بڑی، مشترکہ یا بدلنے والی ہو۔ تصویر، پچاس صفحات پر استعمال ہونے والا لوگو، یا ہفتہ وار اپ ڈیٹ ہونے والی تصویر فائل کے طور پر رہنی چاہیے جسے براؤزر کیش کر سکے۔</p>\n<p>زیادہ تر تصاویر اس لکیر کے ایک طرف واضح طور پر آتی ہیں۔ مشکل صورت درمیانی ہوتی ہیں، اور باقی مضمون انہیں پرکھنے کے بارے میں ہے۔</p>\n<p>شک ہو تو ناپیں۔ نیچے دی گئی حدیں آپ کو احساس کے بجائے نمبر دیتی ہیں جن سے فیصلہ کریں۔</p>\n<h2 id=\"size-thresholds\">سائز کی حدیں: نمبر</h2>\n<p>2 KB سے نیچے، بغیر سوچے ایمبیڈ کریں۔ اوور ہیڈ ایک کلو بائٹ سے کم ہوتا ہے، بچائی گئی درخواست کہیں زیادہ قیمتی ہوتی ہے، اور کوئی صارف قیمت کبھی محسوس نہیں کرے گا۔</p>\n<p>2 KB سے 10 KB کے درمیان، ایمبیڈ کرنا اکثر پھر بھی درست ہوتا ہے۔ اوور ہیڈ زیادہ سے زیادہ چند کلو بائٹ ہوتا ہے، اور تصویر اتنی چھوٹی ہوتی ہے کہ کیشنگ بمشکل اہمیت رکھتی ہے۔</p>\n<p>10 KB سے 50 KB کے درمیان، ہر صورت الگ فیصلہ کریں۔ فولڈ سے اوپر والا اہم آئیکن اس کا جواز دے سکتا ہے، مگر ایک صفحے پر آرائشی تصویر شاید نہ دے سکے۔</p>\n<p>50 KB سے اوپر، لنک کرنا تقریباً ہمیشہ بہتر ہوتا ہے۔ صرف اوور ہیڈ 16 KB یا اس سے زیادہ ہوتا ہے، اور براؤزر فائل کو کیش کر کے صفحات پر دوبارہ استعمال کر سکتا تھا۔</p>\n<h2 id=\"caching-trade-off\">کیشنگ کا سمجھوتا</h2>\n<p>کیشنگ ایمبیڈنگ کی چھپی قیمت ہے۔ لنک شدہ تصویر ایک بار ڈاؤن لوڈ ہوتی ہے اور ہر اس صفحے پر دوبارہ استعمال ہوتی ہے جو اس کا حوالہ دے، جبکہ ایمبیڈ شدہ تصویر ہر صفحے پر دوبارہ ڈاؤن لوڈ ہوتی ہے۔</p>\n<p>پچاس صفحات والی سائٹ پر 10 KB لوگو پر غور کریں۔ لنک شدہ، اس کی قیمت ایک بار 10 KB ہوتی ہے۔ ایمبیڈ شدہ، اس کی قیمت ہر صفحے پر 13 KB ہوتی ہے، جو پورے دورے پر 650 KB بنتی ہے۔</p>\n<p>یہ ریاضی ایک صفحے والے دوروں کے لیے الٹ جاتی ہے۔ جو ناظر ایک صفحہ پڑھتا ہے وہ ایمبیڈ شدہ قیمت ایک بار ادا کرتا ہے، اور بچائی گئی درخواست صفحے کو لنک شدہ سے تیز بنا سکتی ہے۔</p>\n<p>فیصلے سے پہلے اپنا ٹریفک پیٹرن جانیں۔ گہرے دوروں والا بلاگ مشترکہ تصاویر کو لنک کرے، جبکہ ایک صفحے والی لینڈنگ پیج آزادانہ ایمبیڈ کر سکتا ہے۔</p>\n<h2 id=\"http-requests-vs-file-size\">درخواستیں بمقابلہ بائٹ: کیا زیادہ مہنگا ہے</h2>\n<p>ہر تصویری درخواست سرور تک جانے اور واپس آنے کا خرچ لیتی ہے، اور کنکشن کا اوور ہیڈ بھی۔ تیز کنکشن پر یہ قیمت کم ہوتی ہے، مگر سست موبائل کنکشن پر یہ بڑی ہوتی ہے۔</p>\n<p>ایمبیڈنگ گول سفر کو مکمل ختم کر دیتی ہے۔ تصویر HTML کے ساتھ آتی ہے، اس لیے کوئی اضافی انتظار نہیں، کوئی اضافی کنکشن نہیں، اور درخواست ناکام ہونے کا کوئی خطرہ نہیں۔</p>\n<p>مگر ایمبیڈنگ HTML میں ہی بائٹ بڑھاتی ہے، اور HTML رینڈر بلاکنگ ہوتی ہے۔ ایک میگا بائٹ ایمبیڈ شدہ تصاویر والا صفحہ اس وقت تک رینڈر نہیں ہو سکتا جب تک وہ سب ڈاؤن لوڈ نہ ہو جائے۔</p>\n<p>توازن سالوں میں بدل گیا ہے۔ HTTP/2 اور HTTP/3 کے ساتھ درخواستیں پہلے سے سستی ہو گئی ہیں، اس لیے ہر چیز کے لیے ایمبیڈنگ کا کیس کمزور ہو گیا ہے۔</p>\n<h2 id=\"icons-and-logos-embed\">آئیکن اور لوگو: ایمبیڈ کریں</h2>\n<p>آئیکن بہترین ایمبیڈنگ امیدوار ہیں۔ وہ چھوٹے ہوتے ہیں، عام طور پر 2 KB سے نیچے، اور ایک صفحے کو ان میں سے درجن چاہیے ہو سکتے ہیں، جو لنک ہونے پر درجن درخواستیں بنتیں۔</p>\n<p>آئیکن سیٹ کے لیے اسپرائٹ شیٹ یا آئیکن فونٹ ایمبیڈنگ کی جگہ لے سکتے ہیں، اور دونوں غور کے قابل ہیں۔ مگر ایک صفحے پر ایک یا دو آئیکن کے لیے Data URL سادہ اور تیز ہوتا ہے۔</p>\n<p>لوگو قریبی فیصلہ ہے۔ ہر صفحے پر آنے والا 10 KB سے نیچے چھوٹا لوگو ایمبیڈ ہونے پر کیشنگ کا نقصان ہوتا ہے، مگر ایک لینڈنگ پیج پر لوگو ٹھیک ایمبیڈ ہوتا ہے۔</p>\n<p>سائٹ بھر استعمال ہونے والے لوگو کے لیے اسے لنک کریں۔ براؤزر اسے ایک بار کیش کرتا ہے، اور پہلے کے بعد ہر صفحہ تیزی سے لوڈ ہوتا ہے کیونکہ لوگو پہلے سے موجود ہوتا ہے۔</p>\n<h2 id=\"photos-do-not-embed\">تصاویر: ایمبیڈ نہ کریں</h2>\n<p>تصاویر تقریباً کبھی ایمبیڈ نہیں کرنی چاہیے۔ عام ویب تصویر 100 KB سے 500 KB ہوتی ہے، جو اسٹرنگ کے طور پر 130 KB سے 670 KB بن جاتی ہے، اور وہ وزن HTML کے اندر بیٹھتا ہے۔</p>\n<p>HTML کا پھیلاؤ رینڈرنگ میں تاخیر کرتا ہے، کیونکہ براؤزر کو کچھ دکھانے سے پہلے پورا دستاویز ڈاؤن لوڈ کرنا پڑتا ہے۔ لنک شدہ تصاویر والا صفحہ پہلے اپنا متن رینڈر کرتا ہے۔</p>\n<p>تصاویر آئیکن سے زیادہ بدلتی بھی ہیں۔ جب بھی تصویر بدلی جائے تو اس کی اسٹرنگ والا کوڈ ایڈٹ کرنا پڑتا ہے، جو غلطی کا شکار اور جائزہ لینا مشکل ہوتا ہے۔</p>\n<p>ایک استثنا وہ واحد فائل دستاویز ہے جو آف لائن کام کرنی چاہیے۔ ایک ایمبیڈ شدہ تصویر والی رپورٹ یا ای میل قابلِ قبول ہے، کیونکہ اس کا کوئی دوسرا راستہ نہیں۔</p>\n<h2 id=\"css-backgrounds\">CSS پس منظر اور پیٹرن</h2>\n<p>CSS میں چھوٹے دہرائے جانے والے پیٹرن اور بناوٹ اچھے ایمبیڈنگ امیدوار ہیں۔ 2 KB ٹائل جو پس منظر پر دہرائی جائے وہ کم قیمت لیتی ہے اور ہر صفحے پر درخواست بچاتی ہے۔</p>\n<p>آرائشی گریڈینٹ اور شکلیں خالص CSS کے طور پر اور بھی بہتر ہیں، بغیر کسی تصویر کے۔ CSS میں لکھا گریڈینٹ چند درجن حروف لیتا ہے اور مکمل اسکیل ہوتا ہے۔</p>\n<p>بڑی پس منظر تصاویر لنک ہی رہنی چاہیے۔ 200 KB ہیرو پس منظر اسٹائل شیٹ کے اندر 270 KB بن جاتا ہے، اور اسٹائل شیٹ رینڈر بلاکنگ ہوتی ہے، اس لیے صفحہ دیر سے ظاہر ہوتا ہے۔</p>\n<p>جب پس منظر تصویر CSS میں ایمبیڈ ہو تو اسے اسٹائل شیٹ سے الگ کیش نہیں کیا جا سکتا۔ CSS کی ایک لائن بدلیں اور براؤزر کو ہر ایمبیڈ شدہ تصویر دوبارہ ڈاؤن لوڈ کرنی پڑتی ہے۔</p>\n<h2 id=\"html-email\">HTML ای میل: چھوٹی ایمبیڈ کریں، بڑی لنک کریں</h2>\n<p>ای میل وہ ایک جگہ ہے جہاں ایمبیڈنگ اکثر ضروری ہوتی ہے نہ کہ اختیاری۔ بہت سے کلائنٹ ڈیفالٹ طور پر ریموٹ تصاویر بلاک کرتے ہیں، اس لیے لنک شدہ تصویر کبھی ظاہر ہی نہ ہو۔</p>\n<p>لوگو اور چھوٹی آرائشی تصاویر ایمبیڈ کریں جو پیغام کو پہچاننے کے قابل بناتی ہیں۔ یہ وہ تصاویر ہیں جو ای میل کے درست لگنے کے لیے ظاہر ہونی چاہیے۔</p>\n<p>بڑی تصاویر کو اس کے بجائے لنک کریں، یا انہیں مکمل چھوڑ دیں۔ بھاری ایمبیڈ شدہ تصویر فون پر پیغام کو آہستہ کھولتی ہے، اور کچھ کلائنٹ ایسے پیغامات مسترد کر دیتے ہیں۔</p>\n<p>ان کلائنٹس میں آزمائیں جو آپ کے سامعین استعمال کرتے ہیں۔ کچھ ان لائن Base64 تصاویر بلاک کرتے ہیں، جو پورا حساب الٹ دیتا ہے اور ہوسٹ شدہ تصاویر کو اس سامعین کے لیے محفوظ انتخاب بنا دیتا ہے۔</p>\n<h2 id=\"api-payloads\">API پے لوڈ: Base64 معیار ہے</h2>\n<p>API ویب صفحات سے مختلف دنیا ہیں۔ JSON بائنری ڈیٹا نہیں لے جا سکتا، اس لیے JSON پے لوڈ کے اندر سفر کرنے والی تصویر Base64 ہونی چاہیے، اور لنک کرنے کا کوئی آپشن نہیں۔</p>\n<p>یہاں فیصلہ ایمبیڈ بمقابلہ لنک نہیں، بلکہ یہ ہے کہ تصویر پے لوڈ میں ہے یا نہیں۔ چھوٹا اوتار یا دستخط تصویر ٹھیک بیٹھتی ہے، جبکہ کئی میگا بائٹ والی تصویر نہیں بیٹھتی۔</p>\n<p>پے لوڈ سائز کی حد پر نظر رکھیں۔ بہت سی API درخواستیں چند میگا بائٹ تک محدود کرتی ہیں، اور 2 MB تصویر 2.7 MB اسٹرنگ بن جاتی ہے جو اکیلی حد سے تجاوز کر سکتی ہے۔</p>\n<p>API استعمال کے لیے انکوڈ کرنے سے پہلے کمپریس کریں۔ انکوڈنگ سے پہلے 200 KB تک کم کی گئی تصویر 270 KB فیلڈ بناتی ہے، جو تقریباً ہر پے لوڈ حد میں آرام سے بیٹھتی ہے۔</p>\n<h2 id=\"measuring-performance\">حقیقی کارکردگی کا اثر ناپنا</h2>\n<p>ایمبیڈنگ کے بارے میں رائے سستی ہوتی ہے، اس لیے ناپیں۔ صفحہ تصویر لنک کر کے لوڈ کریں، وقت نوٹ کریں، پھر تصویر ایمبیڈ کر کے لوڈ کریں اور موازنہ کریں۔</p>\n<p>صرف تیز آفس وائی فائی پر نہیں، سست موبائل کنکشن پر آزمائیں۔ درخواست کی بچت سست نیٹ ورک پر سب سے زیادہ اہمیت رکھتی ہے، جبکہ بائٹ کی قیمت انہی نیٹ ورکس پر سب سے زیادہ اہمیت رکھتی ہے۔</p>\n<p>دونوں ورژن میں کل صفحہ وزن چیک کریں۔ ایمبیڈ شدہ صفحہ 33 فیصد اوور ہیڈ سے بھاری ہوتا ہے، اور یہ وزن ہر کارکردگی آڈٹ میں ظاہر ہوتا ہے۔</p>\n<p>دہرائے جانے والے دورے بھی چیک کریں۔ پہلا دورہ ایمبیڈنگ کے حق میں ہو سکتا ہے، جبکہ دوسرا دورہ لنکنگ کے حق میں، کیونکہ کیش شدہ تصویر دوسری بار کچھ نہیں لیتی۔</p>\n<h2 id=\"alternatives-to-base64\">Base64 ایمبیڈنگ کے متبادل</h2>\n<p>SVG تصاویر کے پاس سستا آپشن ہے: URL انکوڈ شدہ SVG۔ Base64 کے بغیر Data URL میں سیدھا لکھا چھوٹا SVG چھوٹا ہوتا ہے، کیونکہ یہ 33 فیصد اوور ہیڈ چھوڑ دیتا ہے۔</p>\n<p>آئیکن فونٹ اور SVG اسپرائٹ شیٹ بہت سی چھوٹی ایمبیڈ شدہ تصاویر کو ایک کیش شدہ فائل سے بدل دیتے ہیں۔ وہ ایک درخواست لیتے ہیں اور پھر سائٹ کے ہر آئیکن کو اسی سے پیش کرتے ہیں۔</p>\n<p>HTTP/2 سرور پش اور پری لوڈ ہنٹ لنک شدہ تصاویر کو ایمبیڈ شدہ جیسی تیز بنا سکتے ہیں۔ براؤزر تصویر جلد لاتا ہے، اس لیے درخواست کی قیمت سکڑ جاتی ہے۔</p>\n<p>اکثر بدلنے والی تصاویر کے لیے جارحانہ کیشنگ والا کنٹینٹ ڈیلیوری نیٹ ورک ایمبیڈنگ کو صاف شکست دیتا ہے۔ پہلا دورہ تیز ہوتا ہے، اور ہر بعد والا دورہ قریب قریب فوری ہوتا ہے۔</p>\n<h2 id=\"security-and-csp\">سیکیورٹی اور کنٹینٹ سیکیورٹی پالیسی</h2>\n<p>کنٹینٹ سیکیورٹی پالیسی ہیڈر Data URL کو بلاک کر سکتے ہیں۔ سخت پالیسی جو تصاویر کو صرف آپ کے اپنے ڈومین سے اجازت دیتی ہے وہ ایمبیڈ شدہ تصویر کو مسترد کر دے گی، اور تصویر غائب ہو جائے گی۔</p>\n<p>اگر آپ کی سائٹ سخت پالیسی استعمال کرتی ہے تو یا تو img-src ڈائریکٹیو میں data: کی اجازت دیں یا تصاویر کو فائل کے طور پر لنک کریں۔ پالیسی کا فیصلہ آپ کی سیکیورٹی ٹیم کا ہے۔</p>\n<p>ایمبیڈ شدہ تصاویر اپنے مواد کو سادہ آڈٹ سے بھی چھپاتی ہیں۔ آپ کے کوڈ کو اسکین کرنے والا جائزہ لینے والا اسٹرنگ ڈی کوڈ کیے بغیر نہیں دیکھ سکتا کہ تصویر کیا دکھاتی ہے، جو جائزے کو مشکل بنا دیتا ہے۔</p>\n<p>صارف کی اپ لوڈ شدہ تصاویر کے لیے کبھی اندھا ایمبیڈ نہ کریں۔ پہلے تصویر کو ڈی کوڈ اور تصدیق کریں، کیونکہ Base64 اسٹرنگ کوئی بھی فائل لے جا سکتی ہے، جن میں وہ بھی شامل ہے جو تصویر نہیں۔</p>\n<h2 id=\"maintenance-cost\">دیکھ بھال کی قیمت جسے کوئی نہیں گنتا</h2>\n<p>ایمبیڈ شدہ تصویر آپ کے کوڈ کے بیچ میں متن کی دیوار ہوتی ہے۔ یہ فائلوں کو پڑھنا مشکل، جائزہ لینا مشکل اور تلاش کرنا مشکل بنا دیتی ہے، کیونکہ اسٹرنگ میں ہزاروں حروف ہوتے ہیں۔</p>\n<p>ایمبیڈ شدہ تصویر اپ ڈیٹ کرنے کا مطلب ہے اسٹرنگ ڈھونڈنا، اسے بدلنا، اور امید کرنا کہ آپ نے درست والی بدلی۔ لنک شدہ فائلوں کے ساتھ اپ ڈیٹ فائل کی تبدیلی ہوتی ہے، اور کوڈ ویسا ہی رہتا ہے۔</p>\n<p>ورژن کنٹرول بھی متاثر ہوتا ہے۔ تصویر میں ایک لائن کی تبدیلی کوڈ فائل میں ہزار لائنوں کا فرق بن جاتی ہے، جو حقیقی تبدیلیوں کو شور میں ڈبو دیتی ہے۔</p>\n<p>جب ایمبیڈ کرنا ہی ہو تو ایمبیڈ شدہ اسٹرنگ کو الگ فائلوں یا متغیرات میں محفوظ کریں۔ اس سے مرکزی کوڈ پڑھنے کے قابل رہتا ہے اور ہر تصویر الگ سے بدلی جا سکتی ہے۔</p>\n<h2 id=\"decision-checklist\">ایمبیڈ فیصلے کی چیک لسٹ</h2>\n<p>ایمبیڈ کرنے سے پہلے چار سوال پوچھیں۔ کیا تصویر 10 KB سے نیچے ہے؟ کیا یہ سائٹ بھر کے بجائے ایک یا چند صفحات پر ظاہر ہوتی ہے؟ کیا یہ شاذ و نادر بدلتی ہے؟ کیا صفحے کو آف لائن کام کرنا چاہیے؟</p>\n<p>اگر جواب ہاں، ہاں، ہاں اور ہاں ہوں تو ایمبیڈ کریں۔ اگر تین ہاں ہوں اور ایک نہ ہو تو احتیاط سے سوچیں۔ اگر دو یا زیادہ نہ ہوں تو تصویر کو فائل کے طور پر لنک کریں۔</p>\n<p>API پے لوڈ اور ای میل کے لیے چیک لسٹ مختلف ہے، کیونکہ وہاں ایمبیڈنگ اختیاری کے بجائے ضروری ہو سکتی ہے۔ وہاں سوال سائز ہے، انتخاب نہیں: پہلے کمپریس کریں۔</p>\n<p>جب سائٹ بدلے تو فیصلے پر دوبارہ غور کریں۔ جو تصویر لینڈنگ پیج پر ایمبیڈ کرنا درست تھی وہی تصویر پچاس صفحات والی سائٹ کا حصہ بننے پر غلط ہو سکتی ہے۔</p>\n<h2 id=\"revisiting-old-embeds\">پرانے ایمبیڈز پر دوبارہ غور</h2>\n<p>ایمبیڈنگ کے فیصلے بری طرح پرانے ہو جاتے ہیں۔ جو سائٹ ایک لینڈنگ پیج سے شروع ہوئی وہ پچاس صفحات تک بڑھ جاتی ہے، اور ہر صفحے پر ایمبیڈ شدہ لوگو کیشنگ کا نقصان بن جاتا ہے۔</p>\n<p>سال میں ایک بار اپنے ایمبیڈز کا آڈٹ کریں۔ کوڈ بیس میں data:image تلاش کریں، سائز کی فہرست بنائیں، اور پوچھیں کہ کیا ہر ایک اب بھی چیک لسٹ کے تحت اپنی جگہ کماتا ہے۔</p>\n<p>ایمبیڈ کو واپس لنک شدہ فائل میں لے جانا آسان ہے: ڈی کوڈ شدہ تصویر محفوظ کریں، اپ لوڈ کریں، اور اسٹرنگ کو اس کے URL سے بدلیں۔ صفحہ ہلکا ہو جاتا ہے، تصویر کیش ہو جاتی ہے۔</p>\n<p>الٹا قدم بھی اتنا ہی درست ہے۔ جو چھوٹی تصویر بڑی سائٹ پر لنک تھی وہ اس وقت ایمبیڈ کے قابل ہو سکتی ہے جب صفحہ الگ دستاویز بن جائے۔ فیصلہ صورت حال سے کریں۔</p>\n<h2 id=\"quick-reference\">فوری حوالہ: ایمبیڈ یا لنک</h2>\n<p>2 KB سے نیچے آئیکن، ایک صفحے پر چھوٹے لوگو، اور واحد فائل دستاویزات اور ای میل میں تصاویر ایمبیڈ کریں۔ بچائی گئی درخواست شامل بائٹ سے زیادہ قیمتی ہوتی ہے۔</p>\n<p>تصاویر، سائٹ بھر کے لوگو، اور 50 KB سے اوپر کی ہر چیز لنک کریں۔ کیش کی بچت اور رینڈرنگ رفتار درخواست کی بچت سے کہیں زیادہ جیتتی ہے۔</p>\n<p>API کے لیے Base64 معیار ہے، اس لیے پہلے کمپریس کریں اور چھوٹا نتیجہ ایمبیڈ کریں۔ باقی سب کے لیے صفحے کو دونوں طریقوں سے ناپیں اور نمبروں کو فیصلہ کرنے دیں۔</p>\n<p>انکوڈنگ کے لیے <a href=\"/ur/tasveer-ko-base64-mein-convert-karein/\">image to Base64 converter</a> استعمال کریں، اور الٹا کرنے کے لیے <a href=\"/ur/base64-ko-tasveer-mein-convert-karein/\">Base64 to image decoder</a> استعمال کریں۔ مکمل پس منظر کے لیے <a href=\"/ur/blog/tasveer-ko-base64-rehnumai/\">Image to Base64: Complete Guide</a> پڑھیں۔</p>\n";

